package ferry

import java.nio.file.{Files, Path}

import scala.collection.immutable.ListMap
import scala.jdk.CollectionConverters.*

import ferry.Protocol.{Admission, Outcome, Schedule}
import ferry.testkit.tla.{Behaviours, Value}

/**
 * Model → code: replays a behaviour of `formal/Ferry.tla`, generated by TLC, through the code's pure [[Protocol]].
 *
 * Each step of the behaviour is the model's `act`. It is turned into the code's step (an arrival into `submit`, `Due`
 * into `due`, and so on), applied, and checked twice: the code must take the very action the model took (the same `act`
 * record), and the code's state must then equal the model's, variable by variable, under the projection below.
 *
 * The model's free choices are its environment's (who arrives, when a deadline passes, what a call returns), and the
 * code's own choices (which lane, how much of it) are made the same way on both sides, so every behaviour of the model
 * is one the code can follow: a divergence is a disagreement between the two.
 */
object ModelReplay:

  enum Verdict:
    case Conforms(steps: Int)
    case Diverged(step: Int, act: Value, detail: String)

  /** The code's limits for a model configuration (a `.cfg` in `formal`), and its workers. */
  final case class Instance(limits: Protocol.Limits, workers: Set[String])

  def instance(formal: Path, config: String): Instance =
    val assigned = Files
      .readAllLines(formal.resolve(s"$config.cfg"))
      .asScala
      .map(_.trim)
      .collect { case s"$name = $value" => name.trim -> value.trim }
      .toMap
    def int(name: String)  = assigned(name).toLong
    def bool(name: String) = assigned(name) == "TRUE"
    Instance(
      Protocol.Limits(
        maxBatchSize = int("MaxBatch").toInt,
        maxBatchWeight = int("MaxWeight"),
        maxBatchDelayNanos = 1L, // deadlines are never reached: the model's Due steps decide when a lane is due
        maxQueueing = int("MaxQueue").toInt,
        maxQueuedWeight = int("MaxQueuedWeight"),
        direct = bool("Direct"),
        oneCallPerKey = bool("OneCallPerKey")
      ),
      assigned("Workers").stripPrefix("{").stripSuffix("}").split(",").map(_.trim).toSet
    )

  /** The code under replay: callers are numbered by the code, and mapped back to the model's names. */
  final private case class Replay(p: Protocol[String, String], ids: Map[String, Long]):
    def name(id: Long): String =
      p.pending.getOrElse(id, ids.collectFirst { case (n, i) if i == id => n }.getOrElse(s"#$id"))

  private def model(name: String): Value = Value.Model(name)
  private def worker(name: String): Int  = name.stripPrefix("w").toInt

  def replay(
    behaviour: Behaviours.Behaviour,
    instance: Instance,
    rules: Engine.Rules = Engine.Rules.standard
  ): Verdict =
    val keys = behaviour.head("lane") match
      case Value.Fn(pairs) => pairs.keys.toVector.collect { case Value.Model(k) => k }
      case Value.Seq(_)    => Vector.empty
      case other           => sys.error(s"unexpected lane: $other")
    val workers = instance.workers.toVector.sorted

    def names(r: Replay) = Conformance.Names[String](id => model(r.name(id)), w => model(s"w$w"), model)

    def project(r: Replay): ListMap[String, Value] =
      val p = r.p
      ListMap(
        "lane" -> Value.Fn(ListMap.from(keys.map { k =>
          model(k) -> Value.Seq(p.lanes.get(k).fold(Vector.empty)(_.items.map(i => model(r.name(i.caller)))))
        })),
        "sched" -> Value.Fn(ListMap.from(keys.map { k =>
          model(k) -> Value.str(p.lanes.get(k).map(_.schedule) match
            case None                      => "none"
            case Some(Schedule.Waiting(_)) => "waiting"
            case Some(Schedule.Ready)      => "ready"
            case Some(Schedule.Blocked)    => "blocked")
        })),
        "ready" -> Value.Seq(p.ready.toVector.map(model)),
        "busy"  -> Value.Fn(ListMap.from(keys.map(k => model(k) -> Value.int(p.busy.getOrElse(k, 0).toLong)))),
        "batch" -> Value.Fn(ListMap.from(workers.map { w =>
          model(w) -> Value.Seq(
            p.batches.get(worker(w)).fold(Vector.empty)(_.items.toVector.map(i => model(r.name(i.caller))))
          )
        })),
        "open"    -> Value.Bool(p.open),
        "pending" -> Value.Set(p.pending.values.map(model).toSet)
      )

    def expected(s: Behaviours.State): ListMap[String, Value] =
      val pending = (s("caller"), s("answer")) match
        case (Value.Fn(callers), Value.Fn(answers)) =>
          callers.collect {
            case (c, Value.Str(how)) if Set("queued", "direct")(how) && answers(c) == Value.Str("none") => c
          }.toSet
        case other => sys.error(s"unexpected callers: $other")
      ListMap.from(Seq("lane", "sched", "ready", "busy", "batch", "open").map(v => v -> s(v))) + ("pending" -> Value
        .Set(pending))

    def field(act: Value, f: String): Value = act match
      case Value.Rec(fs) => fs(f)
      case other         => sys.error(s"act is not a record: $other")
    def str(v: Value): String = v match
      case Value.Model(n) => n
      case Value.Str(s)   => s
      case other          => sys.error(s"expected a name: $other")
    def long(v: Value): Long = v match
      case Value.Int(n) => n
      case other        => sys.error(s"expected an integer: $other")

    @annotation.tailrec
    def loop(r: Replay, i: Int): Verdict =
      if i >= behaviour.size then Verdict.Conforms(behaviour.size - 1)
      else
        val state                                                                 = behaviour(i)
        val act                                                                   = state("act")
        val name                                                                  = str(field(act, "name"))
        def caller                                                                = str(field(act, "caller"))
        val stepped: Either[String, (Replay, zio.Chunk[Protocol.Action[String]])] = name match
          case "Enqueue" | "Claim" | "Reject" | "Refuse" =>
            val s = rules.submit(
              r.p,
              str(field(act, "key")),
              caller,
              long(field(act, "weight")),
              long(field(act, "rank")),
              0L
            )
            val id = s.result match
              case Admission.Refused(c)  => c
              case Admission.Rejected(c) => c
              case Admission.Queued(c)   => c
              case Admission.Claimed(c)  => c
            Right(Replay(s.next, r.ids.updated(caller, id)) -> s.actions)
          case "Due" =>
            r.p
              .due(str(field(act, "key")))
              .toRight("the code's lane is not waiting")
              .map(s => r.copy(p = s.next) -> s.actions)
          case "Take" =>
            rules.take(r.p, worker(str(field(act, "worker"))), Long.MinValue) match
              case Right(s) => Right(r.copy(p = s.next) -> s.actions)
              case Left(_)  => Left("the code has nothing to take")
          case "Complete" =>
            val outcomes = field(act, "outcomes") match
              case Value.Fn(ps) => ps.map((c, o) => str(c) -> Outcome.valueOf(str(o)))
              case Value.Seq(_) => Map.empty[String, Outcome]
              case other        => sys.error(s"unexpected outcomes: $other")
            rules
              .complete(r.p, worker(str(field(act, "worker"))), id => outcomes(r.name(id)))
              .toRight("the code's worker holds no batch")
              .map(s => r.copy(p = s.next) -> s.actions)
          case "CompleteDirect" =>
            rules
              .completeDirect(r.p, r.ids(caller), Outcome.valueOf(str(field(act, "outcome"))))
              .toRight("the code has no direct call for the caller")
              .map(s => r.copy(p = s.next) -> s.actions)
          case "Cancel" =>
            rules
              .cancel(r.p, r.ids(caller))
              .toRight("the caller is not pending in the code")
              .map(s => r.copy(p = s.next) -> s.actions)
          case "Close" =>
            rules.close(r.p).toRight("the code is already closed").map(s => r.copy(p = s.next) -> s.actions)
          case other => Left(s"the code has no action $other")
        stepped match
          case Left(why)              => Verdict.Diverged(i, act, why)
          case Right((next, actions)) =>
            val taken = actions.lastOption.map(Conformance.encode(_, names(next)))
            val want  = expected(state)
            val got   = project(next)
            if !taken.exists(_.sameAs(act)) then Verdict.Diverged(i, act, s"the code took ${taken.map(_.render)}")
            else
              want.collectFirst { case (v, value) if !value.sameAs(got(v)) => v } match
                case Some(v) => Verdict.Diverged(i, act, s"$v: model ${want(v).render}, code ${got(v).render}")
                case None    => loop(next, i + 1)

    loop(Replay(Protocol.empty(instance.limits), Map.empty), 1)
